"use strict";(self.webpackChunkajaymore=self.webpackChunkajaymore||[]).push([["6043"],{7841(e,t,a){a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>u,frontMatter:()=>s,metadata:()=>n,toc:()=>h});var n=a(9724),o=a(4848),i=a(8453);let s={title:"Atheism 2.0",date:new Date("2014-03-19T17:50:43.000Z"),authors:["ajay"],tags:["Education","Atheism","featured","Religion"],description:"I always preferred being called an agnostic. Although I don\u2019t buy any philosophy that religions profess, I quite didn\u2019t appreciate being called an atheist. Atheism somehow meant vanity for me. There is so much that we do not know about our own nature and the nature of the universe that surrounds us. We are deceived\u2026",image:"./670pxatheism_symbol-svg_.jpg",mdx:{format:"md"}},r,l={image:a(3104).A,authorsImageUrls:[void 0]},h=[];function d(e){let t={a:"a",blockquote:"blockquote",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"I always preferred being called an agnostic. Although I don\u2019t buy any philosophy that religions profess, I quite didn\u2019t appreciate being called an atheist. Atheism somehow meant vanity for me. There is so much that we do not know about our own nature and the nature of the universe that surrounds us. We are deceived by our senses and brain perceptions at almost every stage of life and yet how can we be absolutely certain about our faith. It was this dilemma that kept me from calling myself an atheist. I was open to all the convincing arguments put forward by religions so that I could switch sides with them, but somehow luckily for me that never happened. As I learnt more about religion, the more I distanced myself from it.\xa0"}),"\n","\n",(0,o.jsx)(t.p,{children:"Almost all religions began with exceptional individuals who had extraordinary experiences in their lives. Be it Buddha, Moses, Jesus, Mohammed or saints and sages of the ancient India and abroad. But if we are to consider current research in neuroscience these supposed godly experiences of all these extraordinary men would be simulated in a laboratory in a near foreseeable future. All god experiences are nothing more than psychosomatic experiences and there is enough science literature to back it. If we are to go by statistics alone 99.9% of world population has never had a god experience, but still finds it convenient to believe in one. So yes, if you take pride in belonging to 21st century please don\u2019t buy the hogwash that the religions have to preach."}),"\n",(0,o.jsx)(t.p,{children:"But there are quite a many wonderful things that I have learnt being associated with religious people. My love for these ways of living makes me a kind of religious man, yet who does not really believe in religion, quite paradoxical \u{1F642} . So I preferred being an agnostic until now. Although I believe the world will be a better place to live without religion. Although I am sure the general hatred among the masses will exponentially reduce with the death of religion. And although we will have enough time to focus on the ideals of life and principles of morality when religion is removed from our conscience, I somehow cannot guarantee myself the fruitfulness of the endeavor. There are so many things that we would miss if there wasn\u2019t a religion."}),"\n",(0,o.jsx)(t.p,{children:"Okay! So if I were to just brush aside the idea of religion, there would be so much I will be missing in life. The art of meditation or mindful awareness that I have come to appreciate, where does it stand in absence of religion? The religious congregations where I get to meet so many people whom I cannot meet otherwise, and where the people meet only for the sake of it and not for business, what happens to these communal events in the absence of religion? The grand temples, churches, mosques and other beautiful architectural wonders that are symbols of religions, what significance do they hold in absence of the reason for which they were erected? A filler, a companion in difficult times, what do we have at such times if not god? And so many other aspects of our social and personal life, that are based on religious beliefs and are quite beneficial to our well-being, what would possibly replace them if we cast aside religion. Definitely Atheism can\u2019t replace all of it. If we are to go by current understanding of atheism by the general public, it\u2019s plain boring."}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"We need to revive atheism. We need to make people realize how rewarding it can be, to be secular. And to the rescue comes the man Alain de Botton. He talks about Atheism 2.0 in the below talk and produces a convincing argument."}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.a,{href:"http://embed.ted.com/talks/lang/en/alain_de_botton_atheism_2_0.html",children:"http://embed.ted.com/talks/lang/en/alain_de_botton_atheism_2_0.html"})})]})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},3104(e,t,a){a.d(t,{A:()=>n});let n=a.p+"assets/images/670pxatheism_symbol-svg_-566b02ca0e552d067d13fc66bd15bae2.jpg"},8453(e,t,a){a.d(t,{R:()=>s,x:()=>r});var n=a(6540);let o={},i=n.createContext(o);function s(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(i.Provider,{value:t},e.children)}},9724(e){e.exports=JSON.parse('{"permalink":"/blog/2014/03/19/atheism-2-0","source":"@site/blog/2014-03-19-atheism-2-0/index.md","title":"Atheism 2.0","description":"I always preferred being called an agnostic. Although I don\u2019t buy any philosophy that religions profess, I quite didn\u2019t appreciate being called an atheist. Atheism somehow meant vanity for me. There is so much that we do not know about our own nature and the nature of the universe that surrounds us. We are deceived\u2026","date":"2014-03-19T17:50:43.000Z","tags":[{"inline":true,"label":"Education","permalink":"/blog/tags/education"},{"inline":true,"label":"Atheism","permalink":"/blog/tags/atheism"},{"inline":true,"label":"featured","permalink":"/blog/tags/featured"},{"inline":true,"label":"Religion","permalink":"/blog/tags/religion"}],"readingTime":3.22,"hasTruncateMarker":true,"authors":[{"name":"Ajay More","title":"Maintainer of ajaymore.in","url":"https://github.com/ajaymore","imageURL":"https://avatars.githubusercontent.com/u/7659804?v=4","key":"ajay","page":null}],"frontMatter":{"title":"Atheism 2.0","date":"2014-03-19T17:50:43.000Z","authors":["ajay"],"tags":["Education","Atheism","featured","Religion"],"description":"I always preferred being called an agnostic. Although I don\u2019t buy any philosophy that religions profess, I quite didn\u2019t appreciate being called an atheist. Atheism somehow meant vanity for me. There is so much that we do not know about our own nature and the nature of the universe that surrounds us. We are deceived\u2026","image":"./670pxatheism_symbol-svg_.jpg","mdx":{"format":"md"}},"unlisted":false,"prevItem":{"title":"10 pounds lighter","permalink":"/blog/2014/03/21/10-pounds-lighter"},"nextItem":{"title":"Mangalore City","permalink":"/blog/2014/02/13/mangalore-city"}}')}}]);